SELECT * FROM ( SELECT a.*, ROWNUM AS rnum FROM ( SELECT i.inquiry_no AS inquiryNo, i.member_no AS memberNo, m.member_id AS memberId, m.name AS memberName, i.category, i.title, i.content, i.secret_yn AS secretYn, i.status, i.view_count AS viewCount, i.created_at AS createdAt, i.updated_at AS updatedAt, i.delete_yn AS deleteYn FROM inquiry i JOIN member m ON i.member_no = m.member_no WHERE i.delete_yn = 'N'
AND i.status = #{status}
AND i.category = #{category}
AND (i.title LIKE '%' || #{keyword} || '%' OR i.content LIKE '%' || #{keyword} || '%')
ORDER BY i.created_at DESC ) a WHERE ROWNUM <= #{endRow} ) WHERE rnum > #{startRow}

SELECT COUNT(*) FROM inquiry WHERE delete_yn = 'N'
AND status = #{status}
AND category = #{category}
AND (title LIKE '%' || #{keyword} || '%' OR content LIKE '%' || #{keyword} || '%')
